#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-shader. Shader-only effect: the look comes from the shader, the particle is just a carrier
    // (one quad, lifetime = effect duration, Custom1.x = progress 0..1, Custom1.y = random seed).
    // The prefab is rebuilt from this script: edit here, not in the Inspector.
    public static class MeteorBuild
    {
        const string Effect = "Meteor";
        const string Root = "Assets/VFX/" + Effect;
        const string NoiseTex = "Assets/VFX/_Shared/Textures/Noise/T_Noise_Smooth.png";

        [MenuItem("VFX/MeteorShader/Build")]
        public static void Build()
        {
            Debug.Log("[Meteor] Build started");
            if (!ConfirmSceneSwitch()) { Debug.LogWarning("[Meteor] Build cancelled at the save-scene prompt."); return; }
            EnsureFolders(Root, "Materials", "Prefabs", "Scenes");

            // 1. Shared noise (tileable, linear, repeat) + material on the effect shader
            var noise = ImportNoise(NoiseTex);
            var mat = Material(Root + "/Materials/M_" + Effect + "_Add.mat", VfxBlend.Additive, null, shaderName: "VFX/FX/Meteor");
            mat.SetTexture("_NoiseTex", noise);
            mat.EnableKeyword("_USE_PARTICLE_DATA"); mat.SetFloat("_UseParticle", 1);
            mat.SetFloat("_Aspect", 3f);   // quad 6 x 2
            mat.SetColor("_ColorOuter", new Color(0.55f, 0.06f, 0.02f) * 1.6f);
            mat.SetColor("_ColorMid", new Color(1f, 0.38f, 0.06f) * 2f);
            mat.SetColor("_ColorCore", new Color(1f, 0.92f, 0.6f) * 2.5f);

            var blastNoise = noise;
            var blastMat = Material(Root + "/Materials/M_" + Effect + "_Blast_Add.mat", VfxBlend.Additive, null, shaderName: "VFX/FX/Blast");
            blastMat.SetTexture("_NoiseTex", blastNoise);
            blastMat.EnableKeyword("_USE_PARTICLE_DATA"); blastMat.SetFloat("_UseParticle", 1);
            blastMat.SetColor("_ColorOuter", new Color(0.5f, 0.05f, 0.02f) * 1.6f);
            blastMat.SetColor("_ColorMid", new Color(1f, 0.38f, 0.06f) * 2f);
            blastMat.SetColor("_ColorCore", new Color(1f, 0.92f, 0.6f) * 2.5f);

            // 2. Carrier: one long quad flying diagonally (top-right -> bottom-left); head is at the quad's -X side
            var root = new GameObject("VFX_" + Effect);
            const float life = 0.9f, angle = 45f, dist = 6.5f, blastLife = 0.7f;
            var ps = Particle(root.transform, "Meteor", mat, lifetime: life, size: 2f);
            // head sits 1.9 units from the quad center toward the flight direction, so the head lands exactly on (0,0) at t = life
            float headOff = 1.9f * 0.70710678f, runOff = dist * 0.70710678f;
            ps.transform.localPosition = new Vector3(headOff + runOff, headOff + runOff, 0f);
            var main = ps.main;
            main.startSize3D = true;
            main.startSizeX = 6f; main.startSizeY = 2f; main.startSizeZ = 1f;
            main.startRotation = -angle * Mathf.Deg2Rad;   // billboard rotation is clockwise: -45 puts the head at lower-left
            var vel = ps.velocityOverLifetime;
            vel.enabled = true;
            vel.space = ParticleSystemSimulationSpace.Local;
            float v = dist / life * 0.70710678f;
            vel.x = -v; vel.y = -v; vel.z = 0f;
            FxProgress(ps, VfxBuildKit.Curve(0f, 0f, 1f, 1f), seedMin: 0f, seedMax: 10f);

            // 2b. Impact blast at the landing point, starts when the meteor head arrives
            var blast = Particle(root.transform, "Blast", blastMat, lifetime: blastLife, size: 5f);
            blast.transform.localPosition = Vector3.zero;
            var bmain = blast.main;
            bmain.startDelay = life;
            FxProgress(blast, VfxBuildKit.Curve(0f, 0f, 1f, 1f), seedMin: 0f, seedMax: 10f);

            // 3. Save, validate, preview, demo scene
            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + Effect + ".prefab");
            Finish(prefab, Root, Effect, new[] { 0.3f, 0.6f, 0.85f, 0.95f, 1.05f, 1.2f, 1.4f, 1.58f }, new Vector3(0, 0, -9), Vector3.zero);
        }

        public static void BuildBatch() => RunBatch(Build);

        // ---------------------------------------------------------------- shader-FX helpers

        /// <summary>Custom1.x = progress over lifetime, Custom1.y = random seed; streams packed into TEXCOORD0.xyzw.</summary>
        public static void FxProgress(ParticleSystem ps, ParticleSystem.MinMaxCurve progress, float seedMin = 0f, float seedMax = 10f)
        {
            var cd = ps.customData;
            cd.enabled = true;
            cd.SetMode(ParticleSystemCustomData.Custom1, ParticleSystemCustomDataMode.Vector);
            cd.SetVectorComponentCount(ParticleSystemCustomData.Custom1, 2);
            cd.SetVector(ParticleSystemCustomData.Custom1, 0, progress);
            cd.SetVector(ParticleSystemCustomData.Custom1, 1, new ParticleSystem.MinMaxCurve(seedMin, seedMax));
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.SetActiveVertexStreams(new List<ParticleSystemVertexStream>
            {
                ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Color,
                ParticleSystemVertexStream.UV, ParticleSystemVertexStream.Custom1XY
            });
        }

        /// <summary>Noise textures are data: linear (no sRGB), repeat wrap, single channel kept in R/G.</summary>
        public static Texture2D ImportNoise(string path, int maxSize = 256)
        {
            var ti = (TextureImporter)AssetImporter.GetAtPath(path);
            if (ti == null) throw new System.InvalidOperationException("Noise texture missing: " + path);
            bool dirty = ti.sRGBTexture || ti.wrapMode != TextureWrapMode.Repeat || ti.maxTextureSize != maxSize || ti.alphaSource != TextureImporterAlphaSource.None;
            ti.sRGBTexture = false;
            ti.wrapMode = TextureWrapMode.Repeat;
            ti.maxTextureSize = maxSize;
            ti.alphaSource = TextureImporterAlphaSource.None;
            ti.mipmapEnabled = true;
            if (dirty) ti.SaveAndReimport();
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }
    }
}
#endif
